<section><p class="lead">{{ __('site.gallery_lead', [], $loc) }}</p>@if($media->isEmpty())<p class="lead">{{ __('site.gallery_empty', [], $loc) }}</p>@else<div class="gallery-grid">@foreach($media as $item)<figure class="gallery-item">@if($item->type === 'youtube')<a class="gallery-media" href="{{ $item->external_url }}" target="_blank" rel="noopener" aria-label="Voir {{ $item->title }}"><img src="{{ $item->thumbnail_url }}" alt="{{ $item->title }}"><span class="gallery-play" aria-hidden="true">▶</span></a>@elseif($item->type === 'google_drive')<a class="gallery-media" href="{{ $item->external_url }}" target="_blank" rel="noopener" aria-label="Ouvrir {{ $item->title }}"><div style="height:100%;display:grid;place-items:center;color:#fff;font:600 13px Inter,sans-serif;letter-spacing:.08em;text-transform:uppercase;">Google Drive ↗</div></a>@elseif($item->url)<a class="gallery-media" href="{{ $item->url }}" data-lightbox-src="{{ $item->url }}" data-lightbox-alt="{{ $item->title }}" aria-label="Agrandir {{ $item->title }}"><img src="{{ $item->url }}" alt="{{ $item->title }}"></a>@endif<figcaption class="gallery-caption"><h3>{{ $item->title }}</h3>@if($item->caption)<p>{{ $item->caption }}</p>@endif</figcaption></figure>@endforeach</div>@endif</section>